// Checkout conversion module: tracks paid events and updates revenue metrics
const fs = require('fs');
const path = require('path');

const REVENUE_FILE = path.join(__dirname, '..', 'data', 'revenue.json');

function loadRevenue() {
  try {
    if (fs.existsSync(REVENUE_FILE)) {
      return JSON.parse(fs.readFileSync(REVENUE_FILE, 'utf8'));
    }
  } catch (e) {
    console.error('Failed to load revenue file:', e);
  }
  return { paidEvents: 0, conversionRate: 0, leads: 0 };
}

function saveRevenue(data) {
  fs.writeFileSync(REVENUE_FILE, JSON.stringify(data, null, 2));
}

function recordCheckout(leadId, amount) {
  const revenue = loadRevenue();
  revenue.paidEvents = (revenue.paidEvents || 0) + 1;
  revenue.leads = (revenue.leads || 0) + 1;
  revenue.conversionRate = revenue.paidEvents / revenue.leads;
  revenue.lastCheckout = { leadId, amount, timestamp: new Date().toISOString() };
  saveRevenue(revenue);
  console.log(`Checkout recorded: lead ${leadId}, amount ${amount}`);
  return revenue;
}

function getRevenue() {
  return loadRevenue();
}

module.exports = { recordCheckout, getRevenue };
